function toStartsAt(date, timeLabel) {
  const [clock, period] = timeLabel.split(' ');
  const [hour, minute] = clock.split(':');
  const hour24 = period === 'PM' && hour !== '12' ? hour + 12 : hour;
  return `${date}T${String(hour24).padStart(2, '0')}:${minute}`;
}

